      const annual=goldAnnualChange(html);if(finite(annual)){result.asset={...result.asset,percent:annual,percentBasis:'12M',percentCurrency:'USD',unitLabel:'12M USD/ozt I10 OK'};}
      if(meta.fallbackURL)try{const payload=await request(meta.fallbackURL,true),verified=verifiedGoldHistory(payload,result.asset);if(verified){Object.assign(result,verified);}}catch(e){console.log('Ouro: histórico compatível indisponível '+e);}
