    const asset={...SELIC,price:current.value,delta,percent,percentBasis:'90D',unitLabel:'META SELIC % a.a.'};
    const chart=chooseChart(points,asset,current.stamp,'90D');
    if(!chart||chart.points.length<30||(chart.points[chart.points.length-1].stamp.time-chart.points[0].stamp.time)/86400000<75)throw Error('Curva Meta Selic não cobre 90 dias');
    const row={asset,stamp:current.stamp,chart,quoteVerified:true,fetchedAt:Date.now(),selicValidation:{source:'BCB-SGS',seriesId:432,frequency:'D',unit:'% a.a.',windowDays:90,currentDate:current.stamp.day,currentValue:current.value,comparisonDate:comparison.stamp.day,comparisonValue:comparison.value}};
    if(!validSnapshot(row))throw Error('Cotação Meta Selic reprovada na validação');
